def use(world: World, actor: Actor, bag: Bag, item_id: str) -> int:
    item = bag.remove(item_id)
    if item.kind == "potion":
        healed = actor.heal(item.power)
        world.emit(Event("heal", actor.actor_id, amount=healed))
        return healed
    elif item.kind == "shield_tonic":
        # Designer decision R3.2: shield_tonic increases shield by item.power, caps at 5, no HP healing
        if actor.shield < 5:
            shield_gain = min(item.power, 5 - actor.shield)
            actor.shield += shield_gain
            world.emit(Event("shield_tonic", actor.actor_id, amount=shield_gain))
            return shield_gain
        else:
            # Shield already at max, item is consumed but has no effect
            return 0
    elif item.kind == "antidote":
        # Designer decision R3.2: antidote removes poison without healing or granting shield
        if "poison" in actor.statuses:
            del actor.statuses["poison"]
            world.emit(Event("antidote", actor.actor_id, detail="poison removed"))
            return 1
        else:
            # No poison to remove, item is consumed but has no effect
            return 0
    else:
        bag.add(item)
        raise ValueError("item is not usable")

